def regions_by_slashes(grid: list[str]) -> int:
    n = len(grid)
    parent = list(range(4 * n * n))
    regions = 4 * n * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        nonlocal regions
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
            regions -= 1

    for r in range(n):
        for c in range(n):
            base = 4 * (r * n + c)  # triangles: +0 top, +1 right, +2 bottom, +3 left
            ch = grid[r][c]
            if ch == "/":
                union(base + 0, base + 3)
                union(base + 1, base + 2)
            elif ch == "\\":
                union(base + 0, base + 1)
                union(base + 2, base + 3)
            else:
                union(base + 0, base + 1)
                union(base + 1, base + 2)
                union(base + 2, base + 3)
            if c + 1 < n:
                union(base + 1, base + 4 + 3)          # right meets left of next cell
            if r + 1 < n:
                union(base + 2, base + 4 * n + 0)      # bottom meets top of cell below
    return regions

