def minimum_diameter_after_merge(edges1: list[list[int]], edges2: list[list[int]]) -> int:
    def diameter(edges):
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for a, b in edges:
            adj[a].append(b)
            adj[b].append(a)

        def farthest(src):
            # BFS returning (farthest node, its distance)
            dist = [-1] * n
            dist[src] = 0
            queue = [src]
            for node in queue:
                for nxt in adj[node]:
                    if dist[nxt] < 0:
                        dist[nxt] = dist[node] + 1
                        queue.append(nxt)
            last = queue[-1]  # BFS order ends at a farthest node
            return last, dist[last]

        end, _ = farthest(0)
        _, d = farthest(end)
        return d

    d1, d2 = diameter(edges1), diameter(edges2)
    # radius of a tree with diameter d is ceil(d / 2)
    return max(d1, d2, (d1 + 1) // 2 + (d2 + 1) // 2 + 1)

