        if b <= lo or hi <= a:
            return
        best[node] = max(best[node], h)
        if a <= lo and hi <= b:
            tag[node] = max(tag[node], h)
            return
        mid = (lo + hi) // 2
        raise_to(2 * node, lo, mid, a, b, h)
        raise_to(2 * node + 1, mid, hi, a, b, h)

    result, tallest = [], 0
