    # 2) binary search on a slope; ascending tells the direction
    def search(lo, hi, ascending):
        while lo <= hi:
            mid = (lo + hi) // 2
            value = mountain_arr.get(mid)
            if value == target:
                return mid
            if (value < target) == ascending:
                lo = mid + 1
            else:
                hi = mid - 1
        return -1

    found = search(0, peak, True)         # left side holds the smaller indexes
    if found != -1:
        return found
    return search(peak + 1, n - 1, False)

def count_pairs(nums: List[int], k: int) -> int:
    # bucket every number by gcd(number, k); only that part matters
    groups = Counter(math.gcd(x, k) for x in nums)
    keys = sorted(groups)
    total = 0
    for i, g1 in enumerate(keys):
        c1 = groups[g1]
        if g1 * g1 % k == 0:
            total += c1 * (c1 - 1) // 2          # pairs inside one class
        for g2 in keys[i + 1:]:
            if g1 * g2 % k == 0:
                total += c1 * groups[g2]         # pairs across two classes
    return total

