def push_dominoes(dominoes: str) -> str:
    n = len(dominoes)
    net = [0] * n
    force = 0
    for i, c in enumerate(dominoes):              # rightward pushes
        if c == "R":
            force = n
        elif c == "L":
            force = 0
        else:
            force = max(force - 1, 0)
        net[i] += force
    force = 0
    for i in range(n - 1, -1, -1):                # leftward pushes
        c = dominoes[i]
        if c == "L":
            force = n
        elif c == "R":
            force = 0
        else:
            force = max(force - 1, 0)
        net[i] -= force
    return "".join("R" if f > 0 else "L" if f < 0 else "." for f in net)

