def remove_covered_intervals(intervals: list[list[int]]) -> int:
    # Earlier start first; for equal starts, the longer interval first.
    ordered = sorted(intervals, key=lambda iv: (iv[0], -iv[1]))
    remaining = 0
    max_right = -1
    for _, right in ordered:
        if right > max_right:
            remaining += 1      # not covered by anything before it
            max_right = right
    return remaining

