def _serialize(root):
    out, q, qi = [], [root], 0
    while qi < len(q):
        node = q[qi]; qi += 1
        if node is None:
            out.append(None); continue
        out.append(node.val); q.append(node.left); q.append(node.right)
    while out and out[-1] is None:
