def del_nodes(root: Optional[TreeNode], to_delete: List[int]) -> List[TreeNode]:
    doomed = set(to_delete)
    forest = []
    stack = [(root, True)] if root else []          # (node, parent was removed)
    while stack:
        node, orphan = stack.pop()
        removed = node.val in doomed
        if orphan and not removed:
            forest.append(node)                     # new tree starts here
        for side in ("left", "right"):
            child = getattr(node, side)
            if child is None:
                continue
            stack.append((child, removed))
            if child.val in doomed:
                setattr(node, side, None)           # cut the link to a deleted child
    return forest

