def result_array(nums: List[int]) -> List[int]:
    ranks = {v: i + 1 for i, v in enumerate(sorted(set(nums)))}
    m = len(ranks)
    trees = [[0] * (m + 1), [0] * (m + 1)]          # one Fenwick tree per array
    arrays = [[], []]

    def add(tree, pos):
        while pos <= m:
            tree[pos] += 1
            pos += pos & -pos

    def at_most(tree, pos):                          # how many values have rank <= pos
        total = 0
        while pos:
            total += tree[pos]
            pos -= pos & -pos
        return total

    def place(which, value):
        arrays[which].append(value)
        add(trees[which], ranks[value])

    place(0, nums[0])
    place(1, nums[1])
    for value in nums[2:]:
        r = ranks[value]
        g1 = len(arrays[0]) - at_most(trees[0], r)
        g2 = len(arrays[1]) - at_most(trees[1], r)
        if g1 != g2:
            place(0 if g1 > g2 else 1, value)
        else:
            place(1 if len(arrays[1]) < len(arrays[0]) else 0, value)
    return arrays[0] + arrays[1]

