def max_task_assign(tasks: List[int], workers: List[int], pills: int, strength: int) -> int:
    tasks = sorted(tasks)
    workers = sorted(workers)

    def feasible(k):
        chosen = workers[len(workers) - k:]        # the k strongest, weakest first
        reachable = deque()                        # tasks this worker can do with a pill
        t = 0
        left = pills
        for w in chosen:
            while t < k and tasks[t] <= w + strength:
                reachable.append(tasks[t])
                t += 1
            if not reachable:
                return False
            if reachable[0] <= w:
                reachable.popleft()                # easiest task, no pill needed
            elif left:
                left -= 1
                reachable.pop()                    # pill: take the hardest reachable task
            else:
                return False
        return True

    lo, hi = 0, min(len(tasks), len(workers))
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo

class CountIntervals:
    def __init__(self):
        # Disjoint closed ranges kept sorted, plus the number of integers they cover.
        self.starts = []
        self.ends = []
        self.total = 0

    def add(self, left: int, right: int) -> None:
        # Block [i, j) holds every stored range that overlaps [left, right].
        i = bisect.bisect_left(self.ends, left)
        j = bisect.bisect_right(self.starts, right)
        if i < j:
            left = min(left, self.starts[i])
            right = max(right, self.ends[j - 1])
            for k in range(i, j):
                self.total -= self.ends[k] - self.starts[k] + 1
        self.starts[i:j] = [left]
        self.ends[i:j] = [right]
        self.total += right - left + 1

    def count(self) -> int:
        return self.total

