def is_cousins(root: Optional[TreeNode], x: int, y: int) -> bool:
    info = {}                                     # value -> (parent value, depth)
    queue = deque([(root, None, 0)])
    while queue:
        node, parent, depth = queue.popleft()
        if node.val in (x, y):
            info[node.val] = (parent, depth)
        for child in (node.left, node.right):
            if child:
                queue.append((child, node.val, depth + 1))
    (px, dx), (py, dy) = info[x], info[y]
    return dx == dy and px != py

def count_different_subsequence_gcds(nums: List[int]) -> int:
    top = max(nums)
    present = bytearray(top + 1)
    for x in nums:
        present[x] = 1
    count = 0
    for g in range(1, top + 1):
        if present[g]:
            count += 1                            # g alone has GCD g
            continue
        acc = 0
        # visit only the multiples of g that occur in nums
        for multiple in itertools.compress(range(g, top + 1, g), present[g::g]):
            acc = math.gcd(acc, multiple)
            if acc == g:
                count += 1
                break
    return count

